pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, bytes32 hash) public {
        vm.assume(caller != address(0) && caller != address(c));

        // Fund the caller with at least 1 ether
        vm.deal(caller, 2 ether);

        // Record balance before
        uint256 balanceBefore = caller.balance;

        // Call lockInGuess via prank
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", hash));

        // Record balance after
        uint256 balanceAfter = caller.balance;

        // Rule: if the call succeeds, the caller's balance decreases by exactly 1 ether
        // In reference: requires 1 ether -> sends 1 ether -> balance decreases by 1 ether
        // In mutant: requires 2 ether but only sends 1 ether -> tx reverts because msg.value != 2 ether
        assertTrue(!success || (balanceBefore - balanceAfter == 1 ether));
    }
}

