import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amt) public {
        // Ensure the contract has at least 1 ether to accept lockInGuess
        vm.deal(address(this), 10 ether);
        // Send 1 ether to the contract (constructor requires msg.value == 1 ether)
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent);

        // Set up a random guess, but ensure block number doesn't advance
        vm.assume(amt > 0); // arbitrary condition
        bytes32 guessHash = keccak256(abi.encode(amt));

        // Call lockInGuess with exactly 1 ether
        c.lockInGuess{value: 1 ether}(guessHash);

        // Now settle in the same block (block.number <= guesses[msg.sender].block)
        // Since guesses[msg.sender].block = block.number + 1, this should always fail
        uint256 balanceBefore = address(c).balance;
        (bool settled, ) = address(c).call(abi.encodeWithSelector(c.settle.selector));
        uint256 balanceAfter = address(c).balance;

        // The general rule: settling in the same block must not change the contract balance
        // because the require(block.number > guesses[msg.sender].block) will fail
        assertTrue(balanceBefore == balanceAfter);
    }
