pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address payable caller, uint256 blockOffset) public {
        vm.assume(caller != address(0));
        vm.assume(blockOffset >= 1 && blockOffset <= 256); // blockhash only available for last 256 blocks

        // Fund caller with 2 ether (1 for lockInGuess, 1 for constructor deployment)
        vm.deal(caller, 2 ether);

        // Fund contract with 1 ether from constructor
        vm.deal(address(c), 1 ether);

        // Mine blocks so that when we lock, the target block will have a zero blockhash
        vm.roll(block.number + blockOffset);

        uint256 targetBlock = block.number;
        bytes32 hash = keccak256(abi.encode(caller, block.number));

        // Call lockInGuess
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(hash);

        // Now mine enough blocks so that target block is beyond 256 blocks ago
        vm.roll(targetBlock + 257);

        // The blockhash of targetBlock should now be zero since it's more than 256 blocks ago
        bytes32 blockHash = blockhash(targetBlock);
        vm.assume(blockHash == bytes32(0)); // ensure it's zero

        // Now settle - reference should not transfer, buggy version will transfer
        uint256 balanceBefore = address(caller).balance;

        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("settle()"));

        if (success) {
            // If settle succeeded, it means transfer happened - buggy behavior
            assertTrue(address(caller).balance == balanceBefore + 2 ether);
        } else {
            // If settle reverted, no transfer - correct behavior
            assertTrue(true);
        }
    }
}

