pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 blockOffset) public {
        vm.assume(blockOffset > 1 && blockOffset < 256);
        vm.deal(address(this), 2 ether);
        c.lockInGuess{value: 1 ether}(hash);
        // Mine to the target block and get its blockhash
        uint256 targetBlock = block.number;
        // Move forward blockOffset blocks
        for (uint256 i = 0; i < blockOffset; i++) {
            vm.roll(block.number + 1);
        }
        bytes32 answer = blockhash(targetBlock);
        uint256 balanceBefore = address(c).balance;
        // Call settle
        (bool success,) = address(c).call(abi.encodeWithSignature("settle()"));
        if (!success) {
            // Settle reverted -> no transfer should have happened
            assertTrue(balanceBefore == address(c).balance);
        } else {
            // Settle succeeded
            if (answer == 0) {
                // If answer is zero, transfer should NOT happen
                assertTrue(balanceBefore == address(c).balance);
            } else {
                // If answer is non-zero, transfer happens iff guess == answer
                // But we can't check guess directly; check balance change
                assertTrue(balanceBefore - address(c).balance == 2 ether || balanceBefore == address(c).balance);
            }
        }
    }
}

