        vm.roll(block.number + blockOffset);

        // Try to settle and capture revert
        (bool success, ) = address(c).call(abi.encodeWithSignature("settle()"));

        // The expected behavior: if blockhash of the target block is zero, settle should revert
        // We can check this indirectly: if blockOffset is large enough (>=256), blockhash is guaranteed zero
