pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash) public {
        // Ensure msg.value is exactly 1 ether for lockInGuess
        vm.deal(address(this), 1 ether);

        // Call lockInGuess with 1 ether
        c.lockInGuess{value: 1 ether}(hash);

        // Record the balance before settle
        uint256 balanceBefore = address(this).balance;

        // Warp to after the target block
        // We need to be at a block number > block where lockInGuess was called (block.number + 1)
        // The lockInGuess sets guesses[msg.sender].block = block.number + 1 at the time of call
        // So we need to be at least at block.number + 2 after the call
        vm.roll(block.number + 3);

        // Call settle
        (bool success, ) = address(c).call(abi.encodeWithSignature("settle()"));

        // If settle succeeded, check that balance did not increase if guess equals the blockhash
        if (success) {
            uint256 balanceAfter = address(this).balance;
            // The blockhash for the block where guess was locked is now blockhash(previous block.number + 1)
            // But we cannot compute the actual blockhash here, so we use a different approach:
            // The property: if the guess matches the blockhash, the balance should not increase.
            // Since we don't know the blockhash, we just assert that balance did NOT increase.
            // This holds for the reference (no transfer on match) but fails for the mutant (transfers on match).
            assertTrue(balanceBefore == balanceAfter, "Balance should not change on successful settle");
        } else {
            // If settle reverted, that's also fine (e.g., if answer is 0)
            assertTrue(true);
        }
    }
}

