        vm.roll(block.number + _blockOffset + 2);
        uint256 balanceBefore = address(c).balance;
        c.settle();
        uint256 balanceAfter = address(c).balance;
        bytes32 blockHash = blockhash(block.number - _blockOffset - 1);
        bool wouldMatch = (blockHash != bytes32(0) && _guess == blockHash);
        assertTrue(wouldMatch ? (balanceAfter == balanceBefore - 2 ether) : (balanceAfter == balanceBefore));
    }
}

